From 0605601df556d54c5a32c74e89c89a38cad73dca Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 05:06:26 +0100
Subject: [PATCH] osdaction: use the primary screen when there is no built-in
 one

On desktops with no built-in panel, the layout actions took the output
listed first as built-in, often not the primary one. Now they use the
primary screen, remember it while it's off and make it primary again.

BUG: 522288
---
 common/CMakeLists.txt |  2 +-
 common/osdaction.cpp  | 42 ++++++++++++++++++++++++++++++++++++++----
 2 files changed, 39 insertions(+), 5 deletions(-)

diff --git a/common/CMakeLists.txt b/common/CMakeLists.txt
index 357c8580..7e865491 100644
--- a/common/CMakeLists.txt
+++ b/common/CMakeLists.txt
@@ -2,6 +2,6 @@ add_library(kscreen_common OBJECT control.cpp osdaction.cpp utils.cpp)
 qt_extract_metatypes(kscreen_common)
 ecm_qt_declare_logging_category(kscreen_common HEADER kscreen_daemon_debug.h IDENTIFIER KSCREEN_KDED CATEGORY_NAME kscreen.kded DESCRIPTION "kscreen kded (kscreen)" EXPORT KSCREEN)
 set_property(TARGET kscreen_common PROPERTY POSITION_INDEPENDENT_CODE ON)
-target_link_libraries(kscreen_common PRIVATE Qt::Core KF6::Screen KF6::CoreAddons KF6::I18n)
+target_link_libraries(kscreen_common PRIVATE Qt::Core KF6::Screen KF6::ConfigCore KF6::CoreAddons KF6::I18n)
 target_include_directories(kscreen_common PUBLIC "$<BUILD_INTERFACE:${CMAKE_CURRENT_SOURCE_DIR}/..>")

diff --git a/common/osdaction.cpp b/common/osdaction.cpp
index 0f41f2f9..b788f5e7 100644
--- a/common/osdaction.cpp
+++ b/common/osdaction.cpp
@@ -12,15 +12,47 @@

 #include "osdaction.h"

+#include <KConfig>
+#include <KConfigGroup>
 #include <KLocalizedString>
 #include <KScreen/Config>
 #include <KScreen/Mode>
 #include <KScreen/Output>
 #include <KScreen/SetConfigOperation>
 #include <QPoint>
+#include <QStandardPaths>

 using namespace KScreen;

+static QString outputKey(const OutputPtr &output)
+{
+    return output->hashMd5() + QLatin1Char('/') + output->name();
+}
+
+// Without a built-in panel (e.g. a desktop with two monitors), the primary screen takes its place. It is remembered
+// while only one screen is on, because disabling the primary one makes the other screen primary.
+static OutputPtr builtInStandIn(const OutputList &outputs)
+{
+    QStringList keys{outputKey(outputs.first()), outputKey(outputs.last())};
+    keys.sort();
+    KConfig stateConfig(QStringLiteral("kscreenosdstaterc"), KConfig::SimpleConfig, QStandardPaths::GenericStateLocation);
+    KConfigGroup group(&stateConfig, QStringLiteral("BuiltInStandIn"));
+    const QString pairKey = keys.join(QLatin1Char(' '));
+
+    if (std::ranges::all_of(outputs, &Output::isEnabled)) {
+        const OutputPtr primary = *std::ranges::min_element(outputs, {}, &Output::priority);
+        group.writeEntry(pairKey, outputKey(primary));
+        return primary;
+    }
+
+    const QString remembered = group.readEntry(pairKey, QString());
+    auto it = std::ranges::find(outputs, remembered, outputKey);
+    if (it == outputs.end()) {
+        it = std::ranges::find_if(outputs, &Output::isEnabled);
+    }
+    return it != outputs.end() ? *it : outputs.first();
+}
+
 QList<OsdAction> OsdAction::availableActions()
 {
     return {
@@ -44,10 +76,8 @@ KScreen::SetConfigOperation *OsdAction::applyAction(const QSharedPointer<KScreen
     auto internalIt = std::find_if(outputs.cbegin(), outputs.cend(), [](const auto &output) {
         return output->type() == KScreen::Output::Type::Panel;
     });
-    if (internalIt == outputs.end()) {
-        internalIt = outputs.begin();
-    }
-    const OutputPtr &internal = *internalIt;
+    const bool hasBuiltIn = internalIt != outputs.end();
+    const OutputPtr internal = hasBuiltIn ? *internalIt : builtInStandIn(outputs);
     const OutputPtr &external = *std::find_if(outputs.cbegin(), outputs.cend(), [&internal](const auto &output) {
         return output != internal;
     });
@@ -117,6 +147,10 @@ KScreen::SetConfigOperation *OsdAction::applyAction(const QSharedPointer<KScreen
         break;
     }
     }
+    if (!hasBuiltIn && internal->isEnabled()) {
+        QMap<OutputPtr, uint32_t> priorities{{internal, 1}, {external, 2}};
+        copy->setOutputPriorities(priorities);
+    }
     return new KScreen::SetConfigOperation(copy);
 }

